/**
 * @file lvgl_app_main.c
 * @brief NuttX application entry point for XFC Smart Panel.
 *
 * This is the only file that touches the NuttX task infrastructure.
 * It creates the LVGL task, initializes the app, and runs the
 * event loop. All GUI logic lives in the layered modules below.
 */

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <spawn.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/boardctl.h>
#include <unistd.h>
#include <syslog.h>

#include <nuttx/compiler.h>

#include "app_init.h"
#include "lvgldemo_port.h"

#define LOG_TAG "lvgl_app"
#define APP_LOOP_MIN_SLEEP_MS 1
#define APP_LOOP_MAX_SLEEP_MS 50
#define APP_AUTOSTART_ARG "autostart"

#undef NEED_BOARDINIT

#if defined(CONFIG_BOARDCTL) && !defined(CONFIG_NSH_ARCHINIT)
#  define NEED_BOARDINIT 1
#endif

#ifndef CONFIG_APP_LVGL_APP_AUTOSTART_DELAY_MS
#  define CONFIG_APP_LVGL_APP_AUTOSTART_DELAY_MS 1500
#endif

#ifdef CONFIG_APP_LVGL_APP_AUTOSTART
int lvgl_app_main(int argc, FAR char *argv[]);

static int lvgl_app_autostart_main(int argc, FAR char *argv[])
{
    posix_spawn_file_actions_t actions;
    posix_spawnattr_t attr;
    FAR char * const child_argv[] = {
        APP_AUTOSTART_ARG,
        NULL
    };
    pid_t pid;
    int ret;

    (void)argc;
    (void)argv;

    usleep(CONFIG_APP_LVGL_APP_AUTOSTART_DELAY_MS * 1000);

    ret = posix_spawn_file_actions_init(&actions);
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] autostart actions init failed: %d\n",
               LOG_TAG, ret);
        return ret;
    }

    ret = posix_spawn_file_actions_addopen(&actions, 0, "/dev/null",
                                           O_RDONLY, 0);
    if (ret == 0) {
        ret = posix_spawn_file_actions_addopen(&actions, 1, "/dev/null",
                                               O_WRONLY, 0);
    }

    if (ret == 0) {
        ret = posix_spawn_file_actions_addopen(&actions, 2, "/dev/null",
                                               O_WRONLY, 0);
    }

    if (ret != 0) {
        syslog(LOG_ERR, "[%s] autostart stdio redirect failed: %d\n",
               LOG_TAG, ret);
        posix_spawn_file_actions_destroy(&actions);
        return ret;
    }

    ret = posix_spawnattr_init(&attr);
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] autostart attr init failed: %d\n",
               LOG_TAG, ret);
        posix_spawn_file_actions_destroy(&actions);
        return ret;
    }

    posix_spawnattr_setpriority(&attr, CONFIG_APP_LVGL_APP_PRIORITY);
    posix_spawnattr_setstacksize(&attr, CONFIG_APP_LVGL_APP_STACKSIZE);

    pid = task_spawn("lvgl_app", lvgl_app_main, &actions, &attr,
                     child_argv, NULL);
    if (pid < 0) {
        syslog(LOG_ERR, "[%s] autostart spawn failed: %d\n", LOG_TAG, pid);
    } else {
        syslog(LOG_INFO, "[%s] autostart pid=%d\n", LOG_TAG, pid);
    }

    posix_spawnattr_destroy(&attr);
    posix_spawn_file_actions_destroy(&actions);

    return pid < 0 ? -pid : 0;
}

constructor_fuction static void lvgl_app_autostart_init(void)
