+#include "framework/utils/ring_buffer.h"
+
+#include <errno.h>
+
+int lvgl_app_ring_buffer_init(lvgl_app_ring_buffer_t *rb,
+                              uint8_t *storage,
+                              size_t capacity)
+{
+  if (rb == NULL || storage == NULL || capacity == 0)
+    {
+      return -EINVAL;
+    }
+
+  rb->buffer = storage;
+  rb->capacity = capacity;
+  rb->head = 0;
+  rb->tail = 0;
+  rb->used = 0;
+
+  return 0;
+}
+
+void lvgl_app_ring_buffer_reset(lvgl_app_ring_buffer_t *rb)
+{
+  if (rb != NULL)
+    {
+      rb->head = 0;
+      rb->tail = 0;
+      rb->used = 0;
+    }
+}
+
+size_t lvgl_app_ring_buffer_write(lvgl_app_ring_buffer_t *rb,
+                                  const uint8_t *data,
+                                  size_t len)
+{
+  size_t written = 0;
+
+  if (rb == NULL || data == NULL)
+    {
+      return 0;
+    }
+
+  while (written < len && rb->used < rb->capacity)
+    {
+      rb->buffer[rb->head] = data[written];
+      rb->head = (rb->head + 1u) % rb->capacity;
+      rb->used++;
+      written++;
+    }
+
+  return written;
+}
+
+size_t lvgl_app_ring_buffer_read(lvgl_app_ring_buffer_t *rb,
+                                 uint8_t *data,
+                                 size_t len)
+{
+  size_t read_len = 0;
+
+  if (rb == NULL || data == NULL)
+    {
+      return 0;
+    }
+
+  while (read_len < len && rb->used > 0)
+    {
+      data[read_len] = rb->buffer[rb->tail];
+      rb->tail = (rb->tail + 1u) % rb->capacity;
+      rb->used--;
+      read_len++;
+    }
+
+  return read_len;
+}
+
+size_t lvgl_app_ring_buffer_used(const lvgl_app_ring_buffer_t *rb)
+{
+  return rb != NULL ? rb->used : 0;
+}
+
+size_t lvgl_app_ring_buffer_free(const lvgl_app_ring_buffer_t *rb)
+{
+  return rb != NULL ? rb->capacity - rb->used : 0;
+}
+
+bool lvgl_app_ring_buffer_empty(const lvgl_app_ring_buffer_t *rb)
+{
+  return rb == NULL || rb->used == 0;
+}
