+int lvgl_app_mem_pool_init(lvgl_app_mem_pool_t *pool,
+                           void *storage,
+                           size_t storage_size,
+                           size_t block_size,
+                           size_t block_count)
+{
+  if (pool == NULL || storage == NULL || block_size == 0 ||
+      block_count == 0 ||
+      block_count > CONFIG_LVGL_APP_FRAMEWORK_UTILS_MEM_POOL_BLOCKS ||
+      storage_size < block_size * block_count)
+    {
+      return -EINVAL;
+    }
+
+  pool->storage = (uint8_t *)storage;
+  pool->block_size = block_size;
+  pool->block_count = block_count;
+  memset(pool->used, 0, sizeof(pool->used));
+
+  return 0;
+}
+
+void *lvgl_app_mem_pool_alloc(lvgl_app_mem_pool_t *pool)
+{
+  size_t i;
+
+  if (pool == NULL)
+    {
+      return NULL;
+    }
+
+  for (i = 0; i < pool->block_count; i++)
+    {
+      if (!pool->used[i])
+        {
+          pool->used[i] = true;
+          return &pool->storage[i * pool->block_size];
+        }
+    }
+
+  return NULL;
+}
+
+int lvgl_app_mem_pool_free(lvgl_app_mem_pool_t *pool, void *ptr)
+{
+  uintptr_t base;
+  uintptr_t addr;
+  size_t offset;
+  size_t index;
+
+  if (pool == NULL || ptr == NULL)
+    {
+      return -EINVAL;
+    }
+
+  base = (uintptr_t)pool->storage;
+  addr = (uintptr_t)ptr;
+
+  if (addr < base)
+    {
+      return -EINVAL;
+    }
+
+  offset = (size_t)(addr - base);
+  if (offset >= pool->block_size * pool->block_count ||
+      (offset % pool->block_size) != 0)
+    {
+      return -EINVAL;
+    }
+
+  index = offset / pool->block_size;
+  if (!pool->used[index])
+    {
+      return -EINVAL;
+    }
+
+  pool->used[index] = false;
+  return 0;
+}
+
+size_t lvgl_app_mem_pool_available(const lvgl_app_mem_pool_t *pool)
+{
+  size_t count = 0;
+  size_t i;
+
+  if (pool == NULL)
+    {
+      return 0;
+    }
+
+  for (i = 0; i < pool->block_count; i++)
+    {
+      if (!pool->used[i])
+        {
+          count++;
+        }
+    }
+
+  return count;
+}
