+      head->next = head;
+    }
+}
+
+bool lvgl_app_list_empty(const lvgl_app_list_node_t *head)
+{
+  return head == NULL || head->next == head;
+}
+
+void lvgl_app_list_add_tail(lvgl_app_list_node_t *head,
+                            lvgl_app_list_node_t *node)
+{
+  if (head == NULL || node == NULL)
+    {
+      return;
+    }
+
+  node->prev = head->prev;
+  node->next = head;
+  head->prev->next = node;
+  head->prev = node;
+}
+
+void lvgl_app_list_remove(lvgl_app_list_node_t *node)
+{
+  if (node == NULL || node->prev == NULL || node->next == NULL)
+    {
+      return;
+    }
+
+  node->prev->next = node->next;
+  node->next->prev = node->prev;
+  node->prev = NULL;
+  node->next = NULL;
+}
