+
+static lvgl_app_soft_timer_slot_t g_timers
+  [CONFIG_LVGL_APP_FRAMEWORK_UTILS_SOFT_TIMER_MAX];
+
+static bool lvgl_app_soft_timer_due(uint32_t now_ms, uint32_t expiry_ms)
+{
+  return (int32_t)(now_ms - expiry_ms) >= 0;
+}
+
+void lvgl_app_soft_timer_init(void)
+{
+  memset(g_timers, 0, sizeof(g_timers));
+}
+
+int lvgl_app_soft_timer_create(lvgl_app_soft_timer_cb_t cb, void *user)
+{
+  int i;
+
+  if (cb == NULL)
+    {
+      return -EINVAL;
+    }
+
+  for (i = 0; i < CONFIG_LVGL_APP_FRAMEWORK_UTILS_SOFT_TIMER_MAX; i++)
+    {
+      if (!g_timers[i].allocated)
+        {
+          g_timers[i].allocated = true;
+          g_timers[i].cb = cb;
+          g_timers[i].user = user;
+          return i;
+        }
+    }
+
+  return -ENOSPC;
+}
+
+int lvgl_app_soft_timer_start(int timer_id,
+                              uint32_t now_ms,
+                              uint32_t period_ms,
+                              bool periodic)
+{
+  if (timer_id < 0 ||
+      timer_id >= CONFIG_LVGL_APP_FRAMEWORK_UTILS_SOFT_TIMER_MAX ||
+      !g_timers[timer_id].allocated || period_ms == 0)
+    {
+      return -EINVAL;
+    }
+
+  g_timers[timer_id].period_ms = period_ms;
+  g_timers[timer_id].expiry_ms = now_ms + period_ms;
+  g_timers[timer_id].periodic = periodic;
+  g_timers[timer_id].active = true;
+
+  return 0;
+}
+
+int lvgl_app_soft_timer_stop(int timer_id)
+{
+  if (timer_id < 0 ||
+      timer_id >= CONFIG_LVGL_APP_FRAMEWORK_UTILS_SOFT_TIMER_MAX ||
+      !g_timers[timer_id].allocated)
+    {
+      return -EINVAL;
+    }
+
+  g_timers[timer_id].active = false;
+  return 0;
+}
+
+void lvgl_app_soft_timer_tick(uint32_t now_ms)
+{
+  int i;
+
+  for (i = 0; i < CONFIG_LVGL_APP_FRAMEWORK_UTILS_SOFT_TIMER_MAX; i++)
+    {
+      if (g_timers[i].allocated && g_timers[i].active &&
+          lvgl_app_soft_timer_due(now_ms, g_timers[i].expiry_ms))
+        {
+          if (g_timers[i].periodic)
+            {
+              g_timers[i].expiry_ms = now_ms + g_timers[i].period_ms;
+            }
+          else
+            {
+              g_timers[i].active = false;
+            }
+
+          g_timers[i].cb(g_timers[i].user);
+        }
+    }
+}
