+
+static pthread_mutex_t g_service_lock = PTHREAD_MUTEX_INITIALIZER;
+static lvgl_app_service_t g_services[CONFIG_LVGL_APP_SERVICES_MAX_SERVICES];
+static unsigned int g_service_count;
+
+int lvgl_app_service_manager_init(void)
+{
+  (void)pthread_mutex_lock(&g_service_lock);
+  memset(g_services, 0, sizeof(g_services));
+  g_service_count = 0;
+  (void)pthread_mutex_unlock(&g_service_lock);
+
+  return 0;
+}
+
+void lvgl_app_service_manager_deinit(void)
+{
+  (void)lvgl_app_service_manager_stop_all();
+  (void)pthread_mutex_lock(&g_service_lock);
+  memset(g_services, 0, sizeof(g_services));
+  g_service_count = 0;
+  (void)pthread_mutex_unlock(&g_service_lock);
+}
+
+int lvgl_app_service_manager_register(const char *name,
+                                      int priority,
+                                      lvgl_app_service_start_t start,
+                                      lvgl_app_service_stop_t stop)
+{
+  if (name == NULL || start == NULL || stop == NULL)
+    {
+      return -EINVAL;
+    }
+
+  (void)pthread_mutex_lock(&g_service_lock);
+  if (g_service_count >= CONFIG_LVGL_APP_SERVICES_MAX_SERVICES)
+    {
+      (void)pthread_mutex_unlock(&g_service_lock);
+      return -ENOSPC;
+    }
+
+  g_services[g_service_count].name = name;
+  g_services[g_service_count].priority = priority;
+  g_services[g_service_count].start = start;
+  g_services[g_service_count].stop = stop;
+  g_services[g_service_count].running = false;
+  g_service_count++;
+  (void)pthread_mutex_unlock(&g_service_lock);
+
+  return 0;
+}
+
+int lvgl_app_service_manager_start_all(void)
+{
+  unsigned int i;
+  int ret;
+
+  for (i = 0; i < g_service_count; i++)
+    {
+      if (!g_services[i].running)
+        {
+          ret = g_services[i].start();
+          if (ret < 0)
+            {
+              LVGL_APP_LOGE(SERVICE_MANAGER_TAG, "start %s failed: %d",
+                            g_services[i].name, ret);
+              return ret;
+            }
+
+          g_services[i].running = true;
+          LVGL_APP_LOGI(SERVICE_MANAGER_TAG, "started %s",
+                        g_services[i].name);
+        }
+    }
+
+  return 0;
+}
+
+int lvgl_app_service_manager_stop_all(void)
+{
+  int i;
+
+  for (i = (int)g_service_count - 1; i >= 0; i--)
+    {
+      if (g_services[i].running)
+        {
+          (void)g_services[i].stop();
+          g_services[i].running = false;
+        }
+    }
+
+  return 0;
+}
