+
+static void lvgl_app_ui_theme_rebuild_styles(void)
+{
+  if (g_theme_initialized)
+    {
+      lv_style_reset(&g_screen_style);
+      lv_style_reset(&g_panel_style);
+      lv_style_reset(&g_title_style);
+      lv_style_reset(&g_text_style);
+      lv_style_reset(&g_button_style);
+    }
+  else
+    {
+      lv_style_init(&g_screen_style);
+      lv_style_init(&g_panel_style);
+      lv_style_init(&g_title_style);
+      lv_style_init(&g_text_style);
+      lv_style_init(&g_button_style);
+    }
+
+  lv_style_set_bg_color(&g_screen_style, g_palette.bg);
+  lv_style_set_bg_opa(&g_screen_style, LV_OPA_COVER);
+  lv_style_set_pad_all(&g_screen_style, 12);
+
+  lv_style_set_bg_color(&g_panel_style, g_palette.surface);
+  lv_style_set_bg_opa(&g_panel_style, LV_OPA_COVER);
+  lv_style_set_border_color(&g_panel_style, g_palette.border);
+  lv_style_set_border_width(&g_panel_style, 1);
+  lv_style_set_radius(&g_panel_style, 6);
+  lv_style_set_pad_all(&g_panel_style, 12);
+
+  lv_style_set_text_color(&g_title_style, g_palette.text);
+  lv_style_set_text_font(&g_title_style, LV_FONT_DEFAULT);
+
+  lv_style_set_text_color(&g_text_style, g_palette.muted);
+  lv_style_set_text_font(&g_text_style, LV_FONT_DEFAULT);
