+
+int lvgl_app_selftest_run(void)
+{
+  uint8_t ring_storage[4];
+  uint8_t pool_storage[32];
+  uint8_t in[3] = {1, 2, 3};
+  uint8_t out[3] = {0, 0, 0};
+  lvgl_app_ring_buffer_t rb;
+  lvgl_app_mem_pool_t pool;
+  void *block;
+
+  if (lvgl_app_ring_buffer_init(&rb, ring_storage,
+                                sizeof(ring_storage)) < 0)
+    {
+      return -1;
+    }
+
+  if (lvgl_app_ring_buffer_write(&rb, in, sizeof(in)) != sizeof(in))
+    {
+      return -1;
+    }
+
+  if (lvgl_app_ring_buffer_read(&rb, out, sizeof(out)) != sizeof(out))
+    {
+      return -1;
+    }
+
+  if (out[0] != 1 || out[1] != 2 || out[2] != 3)
+    {
+      return -1;
+    }
+
+  if (lvgl_app_mem_pool_init(&pool, pool_storage, sizeof(pool_storage),
+                             8, 4) < 0)
+    {
+      return -1;
+    }
+
+  block = lvgl_app_mem_pool_alloc(&pool);
+  if (block == NULL)
+    {
+      return -1;
+    }
+
+  return lvgl_app_mem_pool_free(&pool, block);
+}
