static inline void lvgl_app_log_write(lvgl_app_log_level_t level,
                                      const char *module,
                                      const char *fmt, ...)
{
  va_list ap;
  int priority = LOG_INFO;

  if (level == LVGL_APP_LOG_LEVEL_ERROR)
    {
      priority = LOG_ERR;
    }
  else if (level == LVGL_APP_LOG_LEVEL_WARN)
    {
      priority = LOG_WARNING;
    }
  else if (level == LVGL_APP_LOG_LEVEL_DEBUG)
    {
      priority = LOG_DEBUG;
    }

  syslog(priority, "[%s] ", module != NULL ? module : "lvgl_app");
  va_start(ap, fmt);
  vsyslog(priority, fmt, ap);
  va_end(ap);
}
#endif

#define LVGL_APP_LOGE(module, ...) \
  lvgl_app_log_write(LVGL_APP_LOG_LEVEL_ERROR, module, __VA_ARGS__)
