            # dark/cyan/yellow object, not white background
            if not (r>235 and g>235 and b>235):
                mask[y*w+x]=1
    seen=bytearray(w*h)
    comps=[]
    q=deque()
    for y in range(h):
        for x in range(w):
            idx=y*w+x
            if not mask[idx] or seen[idx]:
                continue
            seen[idx]=1; q.append((x,y)); xs=[]; ys=[]; area=0; touch=False
            while q:
                cx,cy=q.popleft(); area+=1; xs.append(cx); ys.append(cy)
                if cx==0 or cy==0 or cx==w-1 or cy==h-1: touch=True
                for nx,ny in ((cx+1,cy),(cx-1,cy),(cx,cy+1),(cx,cy-1)):
