    im=Image.open(p).convert('RGB')
    w,h=im.size
    sw=(w+S-1)//S; sh=(h+S-1)//S
    mask=[[False]*sw for _ in range(sh)]
    pix=im.load()
    for by in range(sh):
        y0=by*S; y1=min(h,y0+S)
        row=mask[by]
        for bx in range(sw):
            x0=bx*S; x1=min(w,x0+S)
            found=False
            for y in range(y0,y1):
                for x in range(x0,x1):
                    r,g,b=pix[x,y]
                    # foreground if not white-ish background
                    if not (r>238 and g>238 and b>238):
                        found=True; break
                if found: break
            row[bx]=found
    seen=[[False]*sw for _ in range(sh)]
    comps=[]
    for y in range(sh):
        for x in range(sw):
            if not mask[y][x] or seen[y][x]: continue
            q=[(x,y)]; seen[y][x]=True; area=0; minx=maxx=x; miny=maxy=y
