def edge_to_alpha(im):
    im=im.convert('RGBA')
    pix=im.load(); w,h=im.size
    seen=bytearray(w*h); q=deque()
    def is_bg(px):
        r,g,b,a=px
        return a==0 or (r>=215 and g>=215 and b>=215)
    def push(x,y):
        i=y*w+x
        if seen[i]: return
        if is_bg(pix[x,y]):
            seen[i]=1; q.append((x,y))
    for x in range(w): push(x,0); push(x,h-1)
    for y in range(h): push(0,y); push(w-1,y)
    while q:
        x,y=q.popleft()
        for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=nx<w and 0<=ny<h: push(nx,ny)
    for y in range(h):
        for x in range(w):
            if seen[y*w+x]:
                r,g,b,a=pix[x,y]
                pix[x,y]=(r,g,b,0)
    return im
im=Image.open(root/'runtime/card_clock_time_overlay.png').convert('RGBA')
