static lv_obj_t *dash_add_panel(lvgl_app_page_home_view_t *view,
                                lv_obj_t *parent,
                                int32_t x,
                                int32_t y,
                                int32_t w,
                                int32_t h,
                                lv_opa_t opa)
{
  lv_obj_t *obj = lv_obj_create(parent);

  dash_apply_panel_style(obj,
                         lv_color_hex(0x092c38),
                         lv_color_hex(0x58e7f0),
                         opa,
                         dash_scale_y(view, 14));
  lv_obj_set_pos(obj, dash_scale_x(view, x), dash_scale_y(view, y));
  lv_obj_set_size(obj, dash_scale_x(view, w), dash_scale_y(view, h));
  return obj;
}

static lv_obj_t *dash_add_panel_screen(lvgl_app_page_home_view_t *view,
                                       lv_obj_t *parent,
                                       int32_t x,
                                       int32_t y,
                                       int32_t w,
                                       int32_t h,
                                       lv_opa_t opa)
{
  return dash_add_panel(view,
                        parent,
                        dash_ref_from_screen_x(x),
                        dash_ref_from_screen_y(y),
                        dash_ref_from_screen_x(w),
                        dash_ref_from_screen_y(h),
                        opa);
}

