uint32_t lvgl_app_assets_image_resource_id(lvgl_app_image_id_t image)
{
  return LVGL_APP_RESOURCE_ID_IMAGE_BASE + (uint32_t)image;
}

const char *lvgl_app_assets_image_path(lvgl_app_image_id_t image)
{
  if ((unsigned int)image >= (unsigned int)LVGL_APP_IMAGE_COUNT)
    {
      return NULL;
    }

  return g_image_paths[image];
}

const char *lvgl_app_assets_image_name(lvgl_app_image_id_t image)
{
  if ((unsigned int)image >= (unsigned int)LVGL_APP_IMAGE_COUNT)
    {
      return "invalid";
    }

  return g_image_names[image];
}

int lvgl_app_assets_register_defaults(void)
{
  int ret = 0;

#ifdef CONFIG_LVGL_APP_ASSETS_REGISTER_DEFAULT_FONT
#  ifdef CONFIG_LV_FONT_MONTSERRAT_14
  ret = lvgl_app_resource_mgr_register(LVGL_APP_RESOURCE_ID_DEFAULT_FONT,
                                       LVGL_APP_RESOURCE_FONT,
                                       &lv_font_montserrat_14);
#  elif defined(CONFIG_LV_FONT_MONTSERRAT_24)
  ret = lvgl_app_resource_mgr_register(LVGL_APP_RESOURCE_ID_DEFAULT_FONT,
                                       LVGL_APP_RESOURCE_FONT,
                                       &lv_font_montserrat_24);
#  endif
  if (ret < 0 && ret != -EEXIST)
    {
      LVGL_APP_LOGE(ASSETS_TAG,
                    "default font register failed ret=%d", ret);
      return ret;
    }

  LVGL_APP_LOGI(ASSETS_TAG, "default font registered ret=%d", ret);
#endif

#ifdef CONFIG_LVGL_APP_ASSETS_EMBEDDED_IMAGES
  for (unsigned int i = 0; i < (unsigned int)LVGL_APP_IMAGE_COUNT; i++)
    {
      const lv_image_dsc_t *image =
        lvgl_app_embedded_image((lvgl_app_image_id_t)i);

      if (image == NULL)
        {
          LVGL_APP_LOGD(ASSETS_TAG,
                        "embedded image[%u] %s not built",
                        i,
                        lvgl_app_assets_image_name(
                          (lvgl_app_image_id_t)i));
          continue;
        }

      LVGL_APP_LOGI(ASSETS_TAG,
                    "register embedded image[%u] %s dsc=%p cf=%u %ux%u stride=%u bytes=%lu",
                    i,
                    lvgl_app_assets_image_name((lvgl_app_image_id_t)i),
                    image,
                    (unsigned int)image->header.cf,
                    (unsigned int)image->header.w,
                    (unsigned int)image->header.h,
                    (unsigned int)image->header.stride,
                    (unsigned long)image->data_size);

      ret = lvgl_app_resource_mgr_register(
        lvgl_app_assets_image_resource_id((lvgl_app_image_id_t)i),
        LVGL_APP_RESOURCE_IMAGE,
        image);
      if (ret < 0 && ret != -EEXIST)
        {
          LVGL_APP_LOGE(ASSETS_TAG,
                        "embedded image[%u] %s register failed ret=%d",
                        i,
                        lvgl_app_assets_image_name(
                          (lvgl_app_image_id_t)i),
                        ret);
          return ret;
        }
    }
#elif defined(CONFIG_LVGL_APP_ASSETS_IMAGE_PATHS)
  for (unsigned int i = 0; i < (unsigned int)LVGL_APP_IMAGE_COUNT; i++)
    {
      if (g_image_paths[i] == NULL)
        {
          LVGL_APP_LOGD(ASSETS_TAG,
                        "path image[%u] %s not registered",
                        i,
                        lvgl_app_assets_image_name(
                          (lvgl_app_image_id_t)i));
          continue;
        }

      LVGL_APP_LOGI(ASSETS_TAG,
                    "register path image[%u] %s path=%s",
                    i,
                    lvgl_app_assets_image_name((lvgl_app_image_id_t)i),
                    g_image_paths[i]);

      ret = lvgl_app_resource_mgr_register(
        lvgl_app_assets_image_resource_id((lvgl_app_image_id_t)i),
        LVGL_APP_RESOURCE_IMAGE,
        g_image_paths[i]);
      if (ret < 0 && ret != -EEXIST)
        {
          LVGL_APP_LOGE(ASSETS_TAG,
                        "path image[%u] %s register failed ret=%d",
                        i,
                        lvgl_app_assets_image_name(
                          (lvgl_app_image_id_t)i),
                        ret);
          return ret;
        }
    }
#endif

  return 0;
}

