int lvgl_app_ui_theme_init(void)
{
#ifdef CONFIG_LVGL_APP_UI_STYLES_DARK_DEFAULT
  g_theme_mode = LVGL_APP_THEME_DARK;
#else
  g_theme_mode = LVGL_APP_THEME_LIGHT;
#endif

  memset(&g_palette, 0, sizeof(g_palette));
  lvgl_app_ui_theme_build_palette(g_theme_mode);
  lvgl_app_ui_theme_rebuild_styles();

  (void)lvgl_app_data_center_set_u32(LVGL_APP_MODEL_KEY_THEME_MODE,
                                     (uint32_t)g_theme_mode);
  return 0;
}

int lvgl_app_ui_theme_set_mode(lvgl_app_theme_mode_t mode)
{
  if (mode != LVGL_APP_THEME_LIGHT && mode != LVGL_APP_THEME_DARK)
    {
      return -EINVAL;
    }

  if (mode == g_theme_mode && g_theme_initialized)
    {
      return 0;
    }

  g_theme_mode = mode;
  lvgl_app_ui_theme_build_palette(mode);
  lvgl_app_ui_theme_rebuild_styles();
  (void)lvgl_app_data_center_set_u32(LVGL_APP_MODEL_KEY_THEME_MODE,
                                     (uint32_t)mode);
  return lvgl_app_event_bus_publish_async(LVGL_APP_EVENT_THEME_CHANGED,
                                          &mode,
                                          sizeof(mode),
                                          0);
}

