static int32_t dash_ref_from_screen_x(int32_t value)
{
  return (int32_t)(((int64_t)value * DASH_REF_W + IMG_BACKGROUND_W / 2) /
                   IMG_BACKGROUND_W);
}

static int32_t dash_ref_from_screen_y(int32_t value)
{
  return (int32_t)(((int64_t)value * DASH_REF_H + IMG_BACKGROUND_H / 2) /
                   IMG_BACKGROUND_H);
}

static uint32_t dash_image_zoom(int32_t dst_w,
                                int32_t dst_h,
                                int32_t src_w,
                                int32_t src_h)
{
  int32_t zoom_w = (int32_t)(((int64_t)dst_w * 256) / src_w);
  int32_t zoom_h = (int32_t)(((int64_t)dst_h * 256) / src_h);
  int32_t zoom = zoom_w < zoom_h ? zoom_w : zoom_h;

  if (zoom < 1)
    {
      zoom = 1;
    }

  return (uint32_t)zoom;
}

const char *lvgl_app_page_home_component_name(
  lvgl_app_home_component_id_t component)
{
