static lv_obj_t *dash_add_image(lvgl_app_page_home_view_t *view,
                                lv_obj_t *parent,
                                lvgl_app_image_id_t image,
                                int32_t x,
                                int32_t y,
                                int32_t w,
                                int32_t h,
                                int32_t src_w,
                                int32_t src_h)
{
  const char *name = lvgl_app_assets_image_name(image);
  const char *path = lvgl_app_assets_image_path(image);
  const void *src = NULL;
  int32_t dst_w = dash_scale_x(view, w);
  int32_t dst_h = dash_scale_y(view, h);
  uint32_t zoom;
  lv_fs_file_t file;
  lv_fs_res_t fs_res;
  lv_obj_t *obj;

  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "image request id=%u name=%s parent=%p design=%ld,%ld %ldx%ld dst=%ldx%ld src=%ldx%ld",
                (unsigned int)image, name, parent,
                (long)x, (long)y, (long)w, (long)h,
                (long)dst_w, (long)dst_h,
                (long)src_w, (long)src_h);

#ifdef CONFIG_LVGL_APP_ASSETS_EMBEDDED_IMAGES
  src = lvgl_app_embedded_image(image);
  if (src != NULL)
    {
      const lv_image_dsc_t *dsc = (const lv_image_dsc_t *)src;

      LVGL_APP_LOGI(HOME_VIEW_TAG,
                    "image embedded id=%u name=%s dsc=%p cf=%u %ux%u stride=%u bytes=%lu",
                    (unsigned int)image, name, dsc,
                    (unsigned int)dsc->header.cf,
                    (unsigned int)dsc->header.w,
                    (unsigned int)dsc->header.h,
                    (unsigned int)dsc->header.stride,
                    (unsigned long)dsc->data_size);
      path = NULL;
    }
  else
    {
      LVGL_APP_LOGW(HOME_VIEW_TAG,
                    "image embedded missing id=%u name=%s path_fallback=%s",
                    (unsigned int)image, name,
                    path != NULL ? path : "none");
    }
#endif

  if (path == NULL)
    {
      if (src == NULL)
        {
          LVGL_APP_LOGE(HOME_VIEW_TAG,
                        "image source missing id=%u name=%s",
                        (unsigned int)image, name);
          return NULL;
        }
    }
  else
    {
      LVGL_APP_LOGI(HOME_VIEW_TAG,
                    "image path validate id=%u name=%s path=%s",
                    (unsigned int)image, name, path);

      fs_res = lv_fs_open(&file, path, LV_FS_MODE_RD);
      if (fs_res != LV_FS_RES_OK)
        {
          struct stat st;
          const char *real_path = path;
          int fd;

          if (path[0] >= 'A' && path[0] <= 'Z' && path[1] == ':')
            {
              real_path = path + 2;
            }

          errno = 0;
          fd = open(real_path, O_RDONLY);
          LVGL_APP_LOGE(HOME_VIEW_TAG,
                        "image open failed path=%s real=%s res=%d fd=%d errno=%d",
                        path, real_path, (int)fs_res, fd, errno);
          if (fd >= 0)
            {
              (void)close(fd);
            }

          if (stat("/rodata", &st) < 0)
            {
              LVGL_APP_LOGE(HOME_VIEW_TAG, "stat /rodata failed errno=%d",
                            errno);
            }
          else
            {
              LVGL_APP_LOGI(HOME_VIEW_TAG, "/rodata mode=0%lo",
                            (unsigned long)st.st_mode);
            }

          return NULL;
        }

